CREATE TRIGGER RefFacility_Version_Create
	ON RefFacility
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RFT_PK, 'RFT'
	FROM inserted
GO
CREATE TRIGGER RefFacility_Version_Update
	ON RefFacility
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RFT_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefFacility_DataChangeHistory
	ON RefFacility
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RFT_PK, 'RFT' FROM inserted
	UNION
	SELECT RFT_PK, 'RFT' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefFacility_DataProcessingResult_Delete
	ON RefFacility
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RFT_PK
	END
GO
